const total=()=>(S.act?S.act.c:0)+(S.food?S.food.c:0);
const CH={p:{c:"Inside CDO",m:"Outside CDO",a:"Anywhere"},car:{a:"Either",y:"I have a car",n:"No car"},b:{300:"₱300",800:"₱800",1500:"₱1,500",5000:"Splurge"},t:{a:"Any length",s:"2 hours",l:"Half day or more",n:"Overnight"},s:{a:"Either",i:"Indoor",o:"Outdoor"},cat:{a:"All categories",...CAT}};
function sel(label,key){return `<fieldset><legend>${label}</legend><div class="chips">`+Object.entries(CH[key]).map(([v,t])=>`<button type="button" class="chip" aria-pressed="${String(S[key])==v}" onclick="setf('${key}','${v}')">${t}</button>`).join("")+`</div></fieldset>`}
function filters(){
 const cu=S.view=="custom";
 return `<a class="back" href="#home">Back</a>
 <div class="steps"><span class="on">1 Choose</span><span${cu||S.gen?' class="on"':""}>2 Your plan</span><span>3 Kit</span></div>
 <h2>${cu?"Build your own date":"Surprise us"}</h2>
 <p class="mute">${cu?"Set the basics, then pick each part yourself.":"Tell us the basics and we choose the rest."}</p>
 ${sel("Where","p")}${sel("Do you have a car?","car")}${sel("Category","cat")}${sel("Budget for two","b")}${sel("How long","t")}${sel("Setting","s")}`
 +(cu?"":`<button class="go" onclick="gen()">Plan my date</button>`);
}
function slot(label,key,pool,item){
 const cu=S.view=="custom",L=key=="act"?A:F;
 return `<div class="card"><div class="lab">${label}</div>`
 +(cu?`<select aria-label="${label}" onchange="pick('${key}',this.value)"><option value="">Choose one</option>${pool.map(x=>`<option value="${L.indexOf(x)}"${item&&item.n==x.n?" selected":""}>${x.n}, about ${peso(x.c)}</option>`).join("")}</select>`:"")
 +(item?`<h3>${item.n}</h3><p>${item.d}</p><p class="tag">About ${peso(item.c)} for two. ${PL[item.p]}. ${CAT[item.cat]?" · "+CAT[item.cat]:""}</p>`:"")
 +`<button class="ghost" onclick="shuffle('${key}')">${cu?"Surprise me":"Try another"}</button></div>`;
}
function plan(){
 const ap=aPool();
 if(!ap.length)return `<div class="card"><p>Nothing fits that combination yet. Try a bigger budget or set the place to Anywhere.</p></div>`;
 const t=total(),bl=S.b>=5000?"your splurge budget":"your "+peso(S.b)+" budget",over=t>S.b?" That is a bit over, so try another pick.":"";
 return `<h2 style="margin-top:22px">Your date</h2>`+slot("Activity","act",ap,S.act)+slot("Food","food",fPool(),S.food)
 +(t?`<div class="total">About ${peso(t)} of ${bl}.${over}</div>`:"")
 +`<p class="note">Ideas and prices are rough estimates and may have changed. Check opening hours and costs before you go.</p>`
 +`<p class="brandline">♥ Date Compass${SITE?" "+SITE:""}</p><div class="bar">`+(S.view=="random"?`<button class="ghost" onclick="gen()">New plan</button>`:"")+`<button onclick="startQ()">10 questions</button><button class="ghost" onclick="startKit()">Kit card</button><button class="ghost" id="cp" onclick="copyPlan()">Copy</button></div>`;
}
function home(){
 const ic={a:'<circle cx="12" cy="12" r="9"/><path d="M15.5 8.5l-2 5-5 2 2-5z"/>',b:'<path d="M3 7h18v3a2 2 0 0 0 0 4v3H3v-3a2 2 0 0 0 0-4z"/>',c:'<path d="M12 20s-7-4.4-7-10a4 4 0 0 1 7-2.5A4 4 0 0 1 19 10c0 5.6-7 10-7 10z"/>'};
 const cir=(k,c,t,d)=>`<div class="cir ${c}"><div><svg viewBox="0 0 24 24">${ic[k]}</svg><b>${t}</b><span>${d}</span></div></div>`;
 return `<div class="hero2"><i class="c1"></i><i class="c2"></i><i class="c3"></i>
 <div class="txt"><h1>Find your best date spot</h1>
 <p class="lead2">Pick a place, budget, and whether you have a car in Cagayan de Oro and Misamis Oriental. Get a full date plan and 10 questions to make it special.</p>
 <a class="cta" href="#custom">Create your date spot</a><a class="cta cta2" href="#random">Surprise me</a></div>
 <div class="phones"><div class="ph p1"><div class="pn"></div><div class="pl">Your date</div><div class="pt"><small>Activity</small><b>Sunset walk at Gaston Park</b></div><div class="pt"><small>Food</small><b>Street food crawl</b></div><div class="pc">Start the questions</div></div>
 <div class="ph p2"><div class="pn"></div><div class="pl">Question 4 of 10</div><div class="pq">What do you need more of from me lately?</div><div class="pc">Next question</div></div></div></div>
 <section class="hiw"><div class="hiwt"><h2>How it works</h2><p class="mute">Choose your basics, get a full plan, then print the kit with 10 questions to talk about. No more running out of ideas.</p></div>
 <div class="circles">${cir("a","ca","Pick the basics","Place and budget")}${cir("b","cb","Get your plan","Activity and food")}${cir("c","cc","Print the kit","With 10 questions")}</div></section>
 <section class="quick"><h2>Start with a vibe</h2><p class="mute">Skip the setup and jump straight to the kind of date you want.</p><div class="quickgrid"><button class="quickcat" onclick="quickCat('romantic')"><b>Romantic</b><span>Sweet & romantic</span></button><button class="quickcat" onclick="quickCat('food')"><b>Food</b><span>Eat & explore</span></button><button class="quickcat" onclick="quickCat('adventure')"><b>Adventure</b><span>Try something new</span></button><button class="quickcat" onclick="quickCat('home')"><b>At Home</b><span>Cozy at home</span></button><button class="quickcat" onclick="quickCat('car')"><b>Car Date</b><span>Hit the road</span></button><button class="quickcat" onclick="quickCat('conversation')"><b>Deep Conversation</b><span>Talk & connect</span></button><button class="quickcat" onclick="quickCat('creative')"><b>Creative</b><span>Make something</span></button><button class="quickcat" onclick="quickCat('games')"><b>Games</b><span>Play together</span></button><button class="quickcat" onclick="quickCat('nature')"><b>Nature</b><span>Fresh air</span></button><button class="quickcat" onclick="quickCat('free')"><b>Free / Low Cost</b><span>Keep it simple</span></button></div></section><p class="note">1,000 wholesome date ideas, including car-friendly options. All ideas are placeholders that still need checking.</p>`;
}
function qview(){
 const i=S.qi,n=S.q.length;
 if(i>=n)return `<div class="q">That was the last one. Hope the date goes well.</div><a class="back" href="#${S.from}">Back to your plan</a>`;
 return `<a class="back" href="#${S.from}">Back to your plan</a><div class="q"><div class="cnt">Question ${i+1} of ${n}</div>${S.q[i]}<div class="brand">Date Compass${SITE?" "+SITE:""}</div></div>
 <button class="ghost" onclick="qn(-1)"${i?"":" disabled"}>Previous</button><button onclick="qn(1)">${i==n-1?"Finish":"Next question"}</button>`;
}
const newCode=()=>"DC-"+Math.random().toString(36).slice(2,6).toUpperCase();
function toggleSurp(){S.surp=!S.surp;render()}

function startKit(){S.from=S.view;if(!S.code)S.code=newCode();S.orderSaved=false;go("kit")}
function readOrderForm(){const g=id=>document.getElementById(id);if(!g("oname"))return;S.order.name=g("oname").value.trim();S.order.partner=g("opartner").value.trim();S.order.occasion=g("ooccasion").value.trim();S.order.date=g("odate").value;S.order.contact=g("ocontact").value.trim();S.order.messenger=g("omessenger").value.trim();S.order.address=g("oaddress")?g("oaddress").value.trim():"";S.order.note=g("onote").value.trim()}
function setDelivery(v){readOrderForm();S.order.delivery=v;render()}
function orderText(){const o=S.order;return "DATE COMPASS KIT ORDER\nOrder code: "+S.code+"\nActivity: "+(S.act?S.act.n:"To be decided")+"\nFood: "+(S.food?S.food.n:"To be decided")+"\nCategory: "+(S.act&&S.act.cat?CAT[S.act.cat]:"Not specified")+"\nSurprise version: "+(S.surp?"Yes":"No")+"\n\nCUSTOMER\nName: "+o.name+"\nPartner name: "+o.partner+"\nOccasion: "+(o.occasion||"Not specified")+"\nKit needed by: "+(o.date||"Not specified")+"\nMobile: "+o.contact+"\nMessenger: "+(o.messenger||"Not provided")+"\n\nFULFILLMENT\nMethod: "+(o.delivery=="delivery"?"Delivery":"Pick up")+"\n"+(o.delivery=="delivery"?"Address: "+(o.address||"Not provided")+"\n":"")+"\nPERSONALIZATION / NOTES\n"+(o.note||"None")+"\n\nEstimated plan total: "+peso(total())+"\nPlease confirm final price, availability, pickup/delivery details, and any partner voucher before production."}
function saveAndOrder(){readOrderForm();const er=document.getElementById("oerr");if(!S.order.name||!S.order.partner||!S.order.contact||!S.order.date){er.textContent="Please add your name, your partner name, mobile number, and the date you need the kit.";return}if(S.order.delivery=="delivery"&&!S.order.address){er.textContent="Please add the delivery address or choose Pick up.";return}saveOrderLocal();S.orderSaved=true;render()}
async function copyOrder(){const b=document.getElementById("copyorder");try{await navigator.clipboard.writeText(orderText());b.textContent="Copied! Paste it in Messenger"}catch(e){b.textContent="Copy failed. Select the order text below."}}
function emailOrder(){location.href="mailto:"+CONTACT_EMAIL+"?subject="+encodeURIComponent("Date Compass kit order "+S.code)+"&body="+encodeURIComponent(orderText())}
function clearOrder(){S.order={name:"",partner:"",occasion:"",date:"",delivery:"pickup",address:"",contact:"",messenger:"",note:""};S.orderSaved=false;saveOrderLocal();render()}
function orderForm(){
 const o=S.order;
 let h='<section class="panel orderbox"><div class="steps"><span class="on">1 Your date</span><span class="on">2 Your details</span><span>3 We prepare it</span></div><h3>Make the kit yours</h3><p class="mute">These details are for your order and the printed card. You do not need an account.</p>';
 h+='<div class="formgrid"><label>Your name *<input id="oname" autocomplete="name" value="'+esc(o.name)+'" placeholder="e.g. Jasper"></label><label>Partner name *<input id="opartner" autocomplete="name" value="'+esc(o.partner)+'" placeholder="e.g. Maria"></label><label>Occasion<input id="ooccasion" value="'+esc(o.occasion)+'" placeholder="Date night, anniversary, birthday..."></label><label>Date you need the kit *<input id="odate" type="date" value="'+esc(o.date)+'"></label><label>Mobile number *<input id="ocontact" type="tel" autocomplete="tel" value="'+esc(o.contact)+'" placeholder="09xx xxx xxxx"></label><label>Messenger name/link<input id="omessenger" value="'+esc(o.messenger)+'" placeholder="Optional, for easier follow-up"></label></div>';
 h+='<fieldset><legend>How should we get the kit to you? *</legend><div class="chips"><button type="button" class="chip" aria-pressed="'+(o.delivery=="pickup")+'" onclick="setDelivery(\'pickup\')">Pick up</button><button type="button" class="chip" aria-pressed="'+(o.delivery=="delivery")+'" onclick="setDelivery(\'delivery\')">Delivery</button></div></fieldset>';
 if(o.delivery=="delivery")h+='<label>Delivery address / landmark *<textarea id="oaddress" rows="3" placeholder="House/building, street, barangay, city + nearby landmark">'+esc(o.address)+'</textarea></label>';
 h+='<label>Special note for us<textarea id="onote" rows="3" placeholder="Card message, colors, surprise instructions, anything we should know...">'+esc(o.note)+'</textarea></label><p id="oerr" class="err" role="alert"></p><div class="orderactions"><button onclick="saveAndOrder()">Save details & create order message</button><button class="ghost" onclick="clearOrder()">Clear details</button></div><p class="note">Your details stay in this browser until you choose to copy or email the order.</p></section>';
 return h;
}
function kitview(){
 if(!S.code)S.code=newCode();
 const o=S.order;
 let h='<a class="back" href="#'+S.from+'">Back to your plan</a><h2>Your date kit</h2><p class="mute">We will collect the details once, then you can send us one clean order message. No back-and-forth hunting for names, dates, or delivery info.</p>';
 h+='<div class="kit'+(S.surp?" sealed":"")+'"><div class="kh">Our date</div>'+(S.surp?'<div class="seal">Sealed surprise. Open on the date.</div>':"");
 h+='<div class="kr"><span>For</span><b>'+(esc(o.partner)||"Your partner")+'</b></div><div class="kr"><span>From</span><b>'+(esc(o.name)||"Your name")+'</b></div><div class="kr"><span>Activity</span><b>'+(S.act?S.act.n:"To be decided")+'</b></div><div class="kr"><span>Food</span><b>'+(S.food?S.food.n:"To be decided")+'</b></div>';
 if(o.occasion)h+='<div class="kr"><span>Occasion</span><b>'+esc(o.occasion)+'</b></div>';
 h+='<div class="vou"><span class="tag">Partner voucher</span><b>Show this card at [Partner name]</b><p>[Offer, for example a free drink with any meal]</p><span class="tag">Valid until [date]. One voucher per card.</span><div class="code">Card code: '+S.code+'</div></div><div class="kf">Planned with Date Compass. The 10 question cards come in the same kit.</div></div>';
 h+='<button class="ghost" onclick="toggleSurp()">'+(S.surp?"Show the plan":"Make it a surprise")+'</button>'+orderForm();
 if(S.orderSaved)h+='<section class="panel success"><h3>Ready to send ✓</h3><p>Your order is organized into one message. Send it through Messenger or email.</p><pre class="ordermsg">'+esc(orderText())+'</pre><div class="orderactions"><button id="copyorder" onclick="copyOrder()">Copy for Messenger</button><button class="ghost" onclick="emailOrder()">Email order</button></div><p class="note">Keep order code <b>'+S.code+'</b> after sending it so we can find the order quickly.</p></section>';
 return h;
}
function cardsview(){
 if(S.q.length<10)S.q=[...Q].sort(()=>Math.random()-.5).slice(0,10);
 return `<a class="back" href="#kit">Back to kit card</a><div class="cardsheet">${S.q.map((t,i)=>`<div class="q"><div class="cnt">${i+1} of 10</div>${t}<div class="brand">Date Compass</div></div>`).join("")}</div><button onclick="try{print()}catch(e){}">Owner: print question cards</button>`;
}
function render(){app.className=S.view=='home'?'wide':'';
 const cur=(S.view=='q'||S.view=='kit')?S.from:S.view;
 document.querySelectorAll('header.site nav a').forEach(a=>{if(a.getAttribute('href')=='#'+cur)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
 const v=S.view;
 app.innerHTML=v=="home"?home():v=="about"?about():v=="contact"?contact():v=="cards"?cardsview():v=="q"?qview():v=="kit"?kitview():filters()+((v=="custom"||S.gen)?plan():"");
}
function quickCat(k){S.cat=k;S.gen=false;S.act=null;S.food=null;go("custom")}
function setf(k,v){
 S[k]=k=="b"?+v:v;
 if(S.view=="random")S.gen=false;
 else{ if(S.act&&!aPool().includes(S.act))S.act=null; if(S.food&&!fPool().includes(S.food))S.food=null }
 render();
}
function gen(){
 const ap=aPool();S.act=ap.length?rnd(ap):null;
 const fp=fPool();S.food=fp.length?rnd(fp):null;S.gen=true;render();
}
function pick(k,i){const L=k=="act"?A:F;S[k]=i===""?null:L[+i];render()}
function shuffle(k){
 const pool=k=="act"?aPool():fPool(),cur=S[k],alt=pool.filter(x=>x!=cur);
 const c=alt.length?rnd(alt):cur;
 if(c){S[k]=c;
  if(k=="act"&&S.view=="random"&&S.food&&S.food.c>Math.max(S.b-c.c,150)){const fp=fPool();if(fp.length)S.food=rnd(fp)}}
 render();
}
function startQ(){S.from=S.view;S.q=[...Q].sort(()=>Math.random()-.5).slice(0,10);S.qi=0;go("q")}
function qn(d){S.qi=Math.max(0,S.qi+d);render();scrollTo(0,0)}
async function copyPlan(){
 const t=`Date plan for us
Activity: ${S.act?S.act.n:"to be decided"}
Food: ${S.food?S.food.n:"to be decided"}
Estimated total: about ${peso(total())}
Planned with Date Compass${SITE?" "+SITE:""}`;
 const b=document.getElementById("cp");
 try{await navigator.clipboard.writeText(t);b.textContent="Copied"}catch(e){b.textContent="Could not copy, try a screenshot"}
}
const RM=matchMedia("(prefers-reduced-motion:reduce)").matches;
let IO=null;
function reveal(){
 if(RM||!("IntersectionObserver" in window))return;
 if(IO)IO.disconnect();
 IO=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){const t=e.target;t.classList.add("in");IO.unobserve(t);setTimeout(()=>{t.classList.add("done");t.style.transitionDelay=""},1000)}}),{threshold:.12,rootMargin:"0px 0px -6% 0px"});
 document.querySelectorAll("#app .hiw,#app .cir,#app .panel,#app details,#app .card,#app .total,#app .big").forEach((el,i)=>{el.classList.add("rv");el.style.transitionDelay=(i%4)*70+"ms";IO.observe(el)});
}
addEventListener("scroll",()=>{const h=document.querySelector("header.site");if(h)h.classList.toggle("sc",scrollY>8)},{passive:true});
function go(h){try{history.pushState(null,"","#"+h)}catch(e){}route(h)}
document.addEventListener("click",e=>{const a=e.target.closest&&e.target.closest('a[href^="#"]');if(!a||e.metaKey||e.ctrlKey)return;e.preventDefault();go(a.getAttribute("href").slice(1)||"home")});
addEventListener("popstate",()=>route());
function route(hh){
 const h=hh||location.hash.slice(1)||"home";
 if((h=="custom"||h=="random")&&S.view=="home"){S.act=S.food=null;S.gen=false}
 if(h=="owner"){const pin=prompt("Owner PIN");if(pin===OWNER_PIN){S.owner=true;document.body.classList.add("owner")}go("home");return}
 if(h=="cards"&&!S.owner){go("home");return}
 if(h=="q"&&!S.q.length){go("home");return}
 if(h=="kit"&&!S.act&&!S.food){go("home");return}
 S.view=h;render();scrollTo(0,0);
 app.classList.remove('enter');void app.offsetWidth;app.classList.add('enter');reveal();
}
addEventListener("hashchange",route);
document.getElementById("yr").textContent=new Date().getFullYear();
route();